{"new_string":"import re


def parse_duration(text):
    """Return seconds for ordered h, m, s parts; see SPEC.md."""
    if not isinstance(text, str) or re.fullmatch(
        r"[0-9]+[hms](?: *[0-9]+[hms])*", text
    ) is None:
        raise ValueError("Invalid duration")

    total = 0
    previous_unit = -1
    for number, unit in re.findall(r"([0-9]+)([hms])", text):
        unit_index = "hms".index(unit)
        if unit_index <= previous_unit:
            raise ValueError("Duration units must be unique and ordered h, m, s")
        total += int(number) * (3600, 60, 1)[unit_index]
        previous_unit = unit_index
    return total
